import{S as o,o as i,c as a,a9 as n,B as d}from"./chunks/framework.DxG24V0C.js";const h=JSON.parse('{"title":"会话日志与上下文投影：模型看到的上下文从哪来","description":"","frontmatter":{"title":"会话日志与上下文投影：模型看到的上下文从哪来"},"headers":[],"relativePath":"deepseek/04-session-log.md","filePath":"deepseek/04-session-log.md","lastUpdated":1788319991000}'),r={name:"deepseek/04-session-log.md"},g=Object.assign(r,{setup(l){const e=[{question:'`dsh` 为什么"不存 messages"，而是存一份 Event 日志再推导？',options:["让模型历史、回放、持久化共用同一份源，避免三份状态失同步","因为 JS 内存不够存 messages","为了故意让代码更难读","因为模型只接受 event 数组作为输入"],correct:0,explanation:'单一事实源使"能回放 == 能持久化 == 能构建上下文"，这是设计核心；其余把日志当成单纯的"接口要求"。'},{question:'为什么 `deriveMessages()` 投影时"跳过 `assistant/chunk`、用 `assistant/message`"？',options:["chunk 保留回放保真，推导用拼好的整块，才做职责分离","因为 chunk 太小无法表示","因为消息已经不需要 chunk","因为 chunk 不包含 provider"],correct:0,explanation:"chunk 是逐 token 的 UI/回放数据；推导要的是拼好的 assistant/message（含 provider/model）。二者目的不同，所以分开。"},{question:'画一下，"model-visible ⟺ logged" 对插件作者最直接的约束是？',options:["往模型里加任何可见输入必须先新增 SessionEventMap 事件并可从日志渲染","要每隔几 turn 手动同步一次消息数组","日志里可以只记录模型输出不必记录输入","只要模型识别了就行，是否记录无所谓"],correct:0,explanation:'invariant 要求"模型可见 ⟺ 已 log（可重建）"；新增模型可见输入必须先加日志事件。其余把"要不要记"交给拍脑袋，违背了这条硬约束。'},{question:'`SurfaceOp` 里的 `{op:"replace", start, end}` 在压缩（compaction）里做什么？',options:["用一条新的 replace 节点遮蔽旧段、derive 时旧节点消失","把整个日志重新排序","把 session 复制一份副本","把消息改成不可变供并行读"],correct:0,explanation:'replace 用新节点替换 [start,end] 的旧 surface 节点，旧段被 shadow 不在 derive 里，正是压缩"缩段放进摘要"的机制。'},{question:"`ctx.sessions.fork(source, boundary)` 从日志分支（fork）要求边界满足什么？",options:["前缀必须在 turn 之间结束，不能再落在开着的 turn 里面","前缀必须落在某个 turn 的正中间","边界点必须位于日志的开头","fork 后必须有整整一份历史删除"],correct:0,explanation:"fork 要求所选前缀结束于稳定 turn 之间（拒绝在开着的回合里分裂），这是从日志提供分支的前提。"}];return(c,s)=>{const t=o("Quiz");return i(),a("div",null,[s[0]||(s[0]=n(`<h1 id="会话日志与上下文投影-模型看到的上下文从哪来" tabindex="-1">会话日志与上下文投影：模型看到的上下文从哪来 <a class="header-anchor" href="#会话日志与上下文投影-模型看到的上下文从哪来" aria-label="Permalink to &quot;会话日志与上下文投影：模型看到的上下文从哪来&quot;">​</a></h1><blockquote><p>本文基于 <code>dsh-v0.1.0-rc.7</code>。项目处于 developer preview，迭代很快，文中机制以该基线为准。</p></blockquote><p>前三篇我们走过了：森林（插件）→ 框架（Cordis）→ 默认 driver（agent-loop）。现在到了整个 <code>dsh</code> 里<strong>最硬、也最能代表它设计哲学</strong>的一个问题——<strong>模型看到的上下文到底从哪来？</strong></p><p>你可能会觉得这是个老问题：不就是把历史消息攒一份传给模型吗。<code>dsh</code> 的答案非常不&quot;当然&quot;：它<strong>不存&quot;历史消息&quot;这个状态</strong>，而是只存一份<strong>追加式的事件日志</strong>，模型的上下文是每次从日志里**推导（derive）**出来的。这一篇就讲清楚：为什么这么做、deriveMessages 怎么推、以及&quot;model-visible ⟺ logged&quot;这条不变量为什么是全文最硬的锚点。</p><p>先给这一篇的核心判断：</p><blockquote><p><strong>在 <code>dsh</code> 里，&quot;能回放&quot;和&quot;持久化&quot;是同一件事——因为它们共享同一个单一事实源：追加式的 <code>SessionEvent</code> 日志。</strong> 模型历史、UI 回放、fork、resume、标题、telemetry，全是这份日志的不同投影。</p></blockquote><h2 id="一、追加式日志-一份不可变的单一事实源" tabindex="-1">一、追加式日志：一份不可变的单一事实源 <a class="header-anchor" href="#一、追加式日志-一份不可变的单一事实源" aria-label="Permalink to &quot;一、追加式日志：一份不可变的单一事实源&quot;">​</a></h2><p><code>docs/subsystems/session.md</code> 开头就点破了这个模型：</p><blockquote><p>A <code>Session</code> is an <strong>append-only log</strong> of typed <code>SessionEvent</code>s — the single source of truth for an agent&#39;s whole interaction history. The LLM message history is <em>derived</em> from the log, never stored separately; replay is re-derivation from the same events.</p></blockquote><p>拆开来有四个设计点：</p><ol><li><strong>追加式（append-only）</strong>。事件只能往尾部加，编号 <code>seq</code> 连续单调（<code>seq = log.length</code>）。谁也不许回改历史。</li><li><strong>带类型（typed）</strong>。<code>SessionEvent</code> 是一个<strong>可判别联合</strong>（discriminated union over <code>type</code>），<code>switch(type)</code> 就能精确窄化 <code>data</code>，而不用到处 cast。</li><li><strong>单一事实源（single source of truth）</strong>。整个 agent 的所有交互过程，只有一个权威记录。别的视图（上下文、回放、UI）都由它派生。</li><li><strong>可扩展（merge-extensible）</strong>。<code>SessionEventMap</code> 允许插件用声明合并（declaration merging）往里追加新事件类型——这又一次接回第 2 篇的&quot;一切皆插件&quot;：连&quot;一条会话里能记录哪种事件&quot;都是插件可扩展的。</li></ol><h3 id="一个-log-条目长什么样" tabindex="-1">一个 log 条目长什么样 <a class="header-anchor" href="#一个-log-条目长什么样" aria-label="Permalink to &quot;一个 log 条目长什么样&quot;">​</a></h3><p><code>SessionEvent</code> 的核心字段，见 <code>session/subsystems/session.md</code> 的类型（这里取其运行相关的字段，源码类型还含依 <code>SurfaceEventType</code> 条件追加的 surface 元数据分支，下节会讲）：</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">type</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> SessionEvent</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">T</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> extends</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> SessionEventType</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> SessionEventType</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt; </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  [</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">K</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> in</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> SessionEventType</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">    type</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> K</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">    seq</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> number</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          // 单调位置，seq = log.length</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">    time</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> number</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">         // epoch ms</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">    data</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> SessionEventMap</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">K</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">    ignorable</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> true</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     // 未知类型时可否跳过</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">T</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span></code></pre></div><p><code>seq</code>/<code>time</code> 是&quot;位置 + 时间&quot;，<code>data</code> 是该事件自己的载荷。<code>ignorable</code> 是个很细但重要的点：一条最新 / 插件新增的<strong>纯信息事件</strong>可以标 <code>ignorable: true</code>，让旧读者在不认识它时安全跳过；而不标这个标记的未知事件，读者必须<strong>拒绝重建</strong>，因为它可能改变整个日志之后所有条目的理解。这是&quot;宁可过度拒绝、不静默残缺&quot;的失败方向设计。</p><p>为什么&quot;日志即事实源&quot;能成立，得益于一个层叠契约：<strong>所有 <code>event.data</code> 必须可无损 JSON 序列化</strong>，而 <code>Session.append</code> 会在写入源头做校验——非 JSON 可序列化（BigInt、函数、class 实例、循环引用等）直接拒。这样一来&quot;日志能落盘&quot;和&quot;日志能回放&quot;合二为一：既然日志格式本身保真，那么&quot;持久化&quot;只需把日志原样存下来，&quot;回放&quot;只需原样读回来——<strong>两者共享这段日志，不需要第二份&quot;历史消息&quot;存储</strong>。</p><h2 id="二、derivemessages-从日志推导模型历史" tabindex="-1">二、deriveMessages()：从日志推导模型历史 <a class="header-anchor" href="#二、derivemessages-从日志推导模型历史" aria-label="Permalink to &quot;二、deriveMessages()：从日志推导模型历史&quot;">​</a></h2><p>日志是&quot;记录了一切&quot;的仓库，但模型要看到的是&quot;装饰好的消息数组&quot;。这个转换就是 <code>deriveMessages()</code>——<code>docs/subsystems/session.md</code> 是这么说的：</p><blockquote><p><code>Session.deriveMessages()</code> projects the event log into the <code>Message[]</code> the model sees — cached (each surface node projected once) and frozen.</p></blockquote><p>一条消息怎么从事件推出来，原则如下（<code>session.md</code> 的 projection rules）：</p><ul><li><code>user/message</code>（用户输入）→ 一个带精确 <code>content</code> 的 user 消息；</li><li><code>assistant/message</code>（拼好的助手消息）→ 带 provider/model 的 assistant 消息；<strong>原始 <code>assistant/chunk</code> 事件属于回放/UI 数据，推导时被跳过</strong>——已拼好的消息才是权威；</li><li><code>tool/result</code>（工具结果）→ 一个携带 <code>tool-result</code> 块的 user 消息；</li><li>其它（<code>turn/*</code>、<code>step/*</code>）是<strong>结构性事件，不投影成消息</strong>。</li></ul><p>还有一个容易被忽略的边界：<strong>空 content 的 <code>assistant/message</code> 也不投影</strong>。max-tokens 把一次输出打断成零内容时，日志仍会留一条 <code>assistant/message</code>（只是为了记录 usage/provider/model），但它不能以&quot;空助手消息&quot;的身份混进模型历史——否则模型会看到一堆空洞的助手回合。</p><p>这个&quot;跳过 chunk、用已拼好消息&quot;的取舍是核心：原始 chunk 保留<strong>回放保真</strong>（UI 想逐 token 还原），而<strong>模型历史</strong>用的是 <code>assistant/message</code> 这个&quot;已经拼好的权威&quot;，两者职责分离。</p><h3 id="surface-推导时-哪些事件算数" tabindex="-1">Surface：推导时&quot;哪些事件算数&quot; <a class="header-anchor" href="#surface-推导时-哪些事件算数" aria-label="Permalink to &quot;Surface：推导时&quot;哪些事件算数&quot;&quot;">​</a></h3><p>更精确地说，推导不是傻白地扫日志，而是维护一个<strong>Surface（有序表面）</strong>。<code>SessionEvent</code> 上只有三种事件带&quot;表面元数据&quot;（<code>SurfaceEventType = user/message | assistant/message | tool/result</code>），它们各自用 <code>surfaceOp</code> 声明自己怎么进表面：</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">type</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> SurfaceOp</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  |</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;append&#39;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  |</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">op</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;replace&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">start</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> number</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">end</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> number</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><ul><li><code>append</code> = 正常向尾部加；</li><li><code>{ op:&#39;replace&#39;, start, end }</code> = 用这条新节点<strong>替换</strong>从 <code>start</code> 到 <code>end</code> 的表面节点，被换掉的（shadowed）必须能被 <code>sourceEventSeqs</code> 追溯到——这正是**压缩（compaction）**做&quot;摘掉一段旧对话、用一个摘要替换&quot;用的机制（第 7 篇专门展开）。</li></ul><p>所以 <code>Session.surface</code> 返回一个<strong>只读的最新表面投影</strong>（<code>nodes</code> = 当前模型可见顺序 + <code>replaceGeneration</code>），<code>deriveMessages()</code> 沿这个表面折叠出消息。这样：</p><ul><li>未带 surface 标记的事件（chunk、turn 边界）<strong>天然缺席</strong>推导；</li><li>压缩的 <code>replace</code> 从推导里<strong>删掉被遮蔽的旧节点</strong>——模型看到的是摘要，不是被删的历史。</li></ul><p><strong>deriveMessages 的缓存</strong>值得一句：每个 surface 节点第一次见到时投影一次并<strong>深冻结</strong>，之后复用；一个 <code>replace</code>（重写）会重建缓存。每次调用返回<strong>新数组</strong>（后面 append 不回充给已持有的调用者），但里面的 <code>Message</code> 对象是共享、深冻结的。这样派生历史不可改写：凡是能无损保留的，都在日志里以冻结形式存在，投影只能读、不能改。</p><h2 id="三、-model-visible-⟺-logged-全文最硬的不变量" tabindex="-1">三、&quot;model-visible ⟺ logged&quot;：全文最硬的不变量 <a class="header-anchor" href="#三、-model-visible-⟺-logged-全文最硬的不变量" aria-label="Permalink to &quot;三、&quot;model-visible ⟺ logged&quot;：全文最硬的不变量&quot;">​</a></h2><p>如果只有&quot;从日志用它&quot;，还不够硬。<code>dsh</code> 把它推到了极致：<strong>任何能到达模型的东西，都必须能从日志重建；否则这条模型的可见输入不该存在。</strong> <code>docs/architecture.md</code> 原话：</p><blockquote><p><strong>Model-visible means logged.</strong> Anything that reaches a model request must be reconstructable from the log, and a runtime invariant asserts it. This is why a new model-visible input requires a new session event: extend <code>SessionEventMap</code> and render from the log.</p></blockquote><p>把这句话反过来读，它在<strong>约束所有插件作者</strong>：</p><ul><li>如果你要往模型的上下文里加一个新东西（注入一段指令、塞一个来自子 agent 的结果），</li><li>你不许&quot;偷偷传一个还没写日志的值&quot;，</li><li>你必须<strong>先新增一个 <code>SessionEventMap</code> 事件</strong>，把这件事记录下来，再从日志渲染给模型。</li></ul><p>为什么这个不变量是&quot;最硬&quot;的？因为四个后果是它想保证的：</p><ol><li><strong>回放即重演</strong>：因为上次的模型输出都能从日志重建，重放整个日志就能得到完全一样的推导 + 一样的模型历史。UI/agent 的 replay 不是&quot;顺便支持&quot;，而是&quot;必然成立&quot;。</li><li><strong>resume 天然可行</strong>：新进程/新对话拿到日志就可以重建上下文，不用额外存一份&quot;上下文快照&quot;，不会因为漏存某份快照而丢上下文。</li><li><strong>持久化简化为日志</strong>：因为上下文能重建，落盘只要存日志、不需要另存&quot;模型历史&quot;，也就天然避免了两份状态失步。</li><li><strong>审计/telemetry 免费</strong>——凡模型可见的，日志都有；凡是日志的，都可以被 telemetry / 调试观测到。</li></ol><p>为了让这条不变量&quot;不只是文档、而是运行时真保证&quot;，<code>dsh</code> 配了 companion <strong>invariant</strong>（<code>@deepseek-ai/dsh-agent-loop/invariant</code>）——它在每次 <code>llm/stream</code> 请求上断言：请求携带的 <code>messages</code> 必须与 <code>session.deriveMessages()</code> 一致、<code>request/header</code> 必须能从日志重建，否则报&quot;log-reconstruction desync&quot;。换句话说，<strong>&quot;这次发给模型的请求 == 就此日志推导出的请求&quot;是在运行时逐请求校验的</strong>。这一层的关键意义在第 3 篇也埋过伏笔：<code>deriveMessages()</code> 从日志读上下文、loop 又往日志写事件，两者闭环——<strong>一个模型请求的输入 = 在它之前日志里全部事件的某个函数</strong>，因此&quot;日志能重建模型请求&quot;就等于&quot;重放日志 == 重游那次会话&quot;，而 invariant 把这一关系从&quot;约定&quot;压成了&quot;断言&quot;。</p><h2 id="四、有资格共享这个单一事实源的-万物皆派生" tabindex="-1">四、有资格共享这个单一事实源的：万物皆派生 <a class="header-anchor" href="#四、有资格共享这个单一事实源的-万物皆派生" aria-label="Permalink to &quot;四、有资格共享这个单一事实源的：万物皆派生&quot;">​</a></h2><p>现在可以把第 2 篇那句口号顺下来了：<strong>不是&quot;模型 context 与持久化分开存&quot;，而是&quot;模型 context（deriveMessages） 的展示、回放都从同一个日志派生&quot;</strong>。<code>dsh</code> 里有多个&quot;从日志派生&quot;的东西：</p><table tabindex="0"><thead><tr><th>能力</th><th>怎么来</th><th>说明</th></tr></thead><tbody><tr><td>模型历史</td><td><code>deriveMessages()</code> / surface</td><td>上面第二节</td></tr><tr><td>Web UI 回放</td><td><code>surface</code> 投影 + <code>assistant/chunk</code></td><td>逐 token 保真回放</td></tr><tr><td>fork（分支）</td><td><code>ctx.sessions.fork(source, boundary)</code></td><td>取一段稳定前缀、在边界（默认当前末尾）之前、在一个 turn 之后，深拷贝种子到子会话</td></tr><tr><td>resume（恢复）</td><td><code>resumeSessionId</code> + 日志重建</td><td>从持久化会话把 agent 重新水合</td></tr><tr><td>标题（title）</td><td><code>sessionTitle</code> 从日志摘要</td><td>派生标题</td></tr><tr><td>telemetry</td><td>订阅 <code>session/event</code></td><td>观测追加事件</td></tr></tbody></table><p>关键在 fork 的设计：<code>fork(source, boundary, childSessionId)</code> 要求选择的前缀<strong>不落在开着的 turn 中间</strong>（拒绝&quot;分裂半途 step&quot;这种边界），而是从稳定点、深克隆 seed 到子会话。这就是&quot;从日志做执行分支&quot;——<strong>分支 = 拷贝一份日志前缀 + 一个全新结尾</strong>，而不是复制一段内存状态。</p><p>（还有&quot;transcript&quot;：human-facing transcript 读日志的追加原始事件，而 Surface 因为会被 replace 遮蔽前段，所以 transcript 读的是 append 来源、不是 surface。）</p><h2 id="五、与三栏对比-谁的-日志即单一事实源-最彻底" tabindex="-1">五、与三栏对比：谁的&quot;日志即单一事实源&quot;最彻底 <a class="header-anchor" href="#五、与三栏对比-谁的-日志即单一事实源-最彻底" aria-label="Permalink to &quot;五、与三栏对比：谁的&quot;日志即单一事实源&quot;最彻底&quot;">​</a></h2><p>三种终端 Agent：OpenCode 用 <code>zod</code> 校验消息 + SQLite 持久化；Codex 会话有 message chunk。它们的日志/持久化<strong>都是&quot;平行于模型的另一份存储&quot;</strong>；而 <code>dsh</code> 把&quot;模型上下文本身&quot;就做成了&quot;从日志推导&quot;，二者<strong>同一份</strong>：持久化就是要&quot;store 日志&quot;，回放/上下文就是要&quot;derive 日志&quot;，模型上下文同样是&quot;日志的一个函数&quot;。</p><table tabindex="0"><thead><tr><th>维度</th><th>OpenCode</th><th>Codex</th><th>DeepSeek Harness</th></tr></thead><tbody><tr><td>模型历史来源</td><td>单独攒的 messages 数组</td><td>会话头 / chunk 累积成一个 Message[]</td><td><strong><code>deriveMessages()</code> 从日志投影</strong></td></tr><tr><td>是否另存&quot;历史&quot;</td><td>是（messages 数组 + DB）</td><td>是（Message 构建）</td><td><strong>否：唯日志，消息靠 derive</strong></td></tr><tr><td>回放</td><td>有</td><td>有</td><td>与持久化/上下文是<strong>同一条</strong>日志</td></tr><tr><td>运行时保证</td><td>校验 schema</td><td>部分</td><td><strong>&quot;model-visible ⟺ logged&quot; invariant 断言</strong></td></tr></tbody></table><p><code>dsh</code> 最彻底的一点是<strong>把&quot;能回放、能持久化、能构建上下文&quot;三项统一到&quot;日志这一件事&quot;上</strong>，并用一个运行时 invariant 去 assert 它。这等于直接对插件作者声明了一条纪律：<strong>&quot;你往模型里塞的任何东西，必须先从日志里长出&quot;</strong>——它用架构和断言把&quot;上下文一致性&quot;这个软绵绵的愿望，压成了一条硬约束。</p><h2 id="六、小结与下一站" tabindex="-1">六、小结与下一站 <a class="header-anchor" href="#六、小结与下一站" aria-label="Permalink to &quot;六、小结与下一站&quot;">​</a></h2><p>把这一篇的线收拢：</p><ol><li><strong>会话日志</strong> = 追加式不可变事件流，<code>seq</code> 连续、JSON 保真，是<strong>唯一</strong>事实源。</li><li><strong>deriveMessages()</strong> = 从日志投影出模型要看的消息；chunk 保回放、assistant/message 供推导。</li><li><strong>Surface</strong> = 给&quot;哪些消息进推导&quot;加一层有序表面，压缩用 <code>replace</code> 遮蔽旧段。</li><li><strong>model-visible ⟺ logged</strong> = 最硬不变量：任何模型可见输入必须能从日志重建，invariant 断言。</li><li><strong>fork/resume/title/telemetry</strong> = 全是同一个日志的不同投影。</li></ol><p>下一篇，环路终于要回到&quot;行动&quot;：agent 已经能用上下文去请求模型、用工具去改变环境——<strong>工具的注册、prompt 注入、执行管线</strong> 到底是怎样把&quot;模型请求一个工具&quot;变成&quot;真实落盘/受限步骤&quot;的？那就走进第 5 篇：<strong>工具系统与执行管线（tools pipeline）</strong>。</p><h2 id="章节小测" tabindex="-1">章节小测 <a class="header-anchor" href="#章节小测" aria-label="Permalink to &quot;章节小测&quot;">​</a></h2>`,52)),d(t,{questions:e})])}}});export{h as __pageData,g as default};
